def HasDensityCharacter (A : Type u) [TopologicalSpace A] (κ : Cardinal.{u}) : Prop :=
  (∃ S : Set A, Dense S ∧ Cardinal.mk S = κ) ∧
    ∀ S : Set A, Dense S → κ ≤ Cardinal.mk S

